<div class="d-flex justify-content-between"><h1 class="h3">Venda #<?= (int)$sale['id'] ?></h1><a class="btn btn-secondary" href="index.php?route=reports">Voltar</a></div><div class="card card-body mb-3"><p><strong>Cliente:</strong> <?= htmlspecialchars($sale['cliente']??'Consumidor não identificado') ?></p><p><strong>Data:</strong> <?= date('d/m/Y H:i',strtotime($sale['criada_em'])) ?></p><p><strong>Status:</strong> <?= htmlspecialchars($sale['status']) ?></p><p><strong>Total:</strong> R$ <?= number_format((float)$sale['total'],2,',','.') ?></p></div><div class="card"><table class="table mb-0"><thead><tr><th>Produto</th><th>Quantidade</th><th>Preço unitário</th><th>Subtotal</th></tr></thead><tbody><?php foreach($sale['itens'] as $i): ?><tr><td><?= htmlspecialchars($i['produto_nome']) ?></td><td><?= (int)$i['quantidade'] ?></td><td>R$ <?= number_format((float)$i['preco_unitario'],2,',','.') ?></td><td>R$ <?= number_format((float)$i['subtotal'],2,',','.') ?></td></tr><?php endforeach; ?></tbody></table></div>
